           const locked = !completed && !isCurrent;
           return (
             <View style={styles.cardWrapper}>
               <ExerciseCard
                 title={item.title}
                 moduleName={item.moduleName}
                 description={`${item.exercises.length} exercise${item.exercises.length > 1 ? "s" : ""} · ${item.description}`}
