     ListHeaderComponent={
       <View style={{ marginBottom: 12 }} />
     }
   data={MODULE_GROUPS}
   keyExtractor={(item) => item.module}
   renderItem={({ item: group }) => {
   const isExpanded = expandedModules[group.module] ?? false;
