   key={sym.name}
   onPress={() => router.push(`/ref?symbol=${sym.name}`)}
   style={({ pressed }) => [
   styles.flexRow,
   styles.symbolRow,
   pressed && { opacity: 0.6 },
   ]}
   accessibilityRole="button"
   accessibilityLabel={`View reference for ${sym.name}`}
    >
     <Text style={[styles.monoSm, { color: derivedColors.primary, flex: 1 }]}>
     {sym.name}()
     </Text>
     </Pressable>
))}
     </View>
   );}}
   />

